installer-script.script:
function installation_check(arch)
{
    var result = true;
    if(arch == 'i386' || arch == 'UB')
    {
        var cr = system.compareVersions(system.version.ProductVersion, '10.13.6');
        if (cr == -1)
        {
            my.result.message = 'Detected macOS version is ' + system.version.ProductVersion + '\n';
            my.result.message += 'Please contact support for a version of the installer compatible with systems prior to macOS 10.13.6';
            my.result.title = 'Fatal Error';
            my.result.type = 'Fatal';

            result = false;
        }
    }
    else if(arch == 'arm64')
    {
        if (system.sysctl('machdep.cpu.brand_string').match('Apple') == null)
        {
            my.result.message = 'This installer is for an Apple Silicon mac. Detected macOS running on an Intel mac\n';
            my.result.message += 'Please contact support for a version of the installer compatible with Intel macs';
            my.result.title = 'Fatal Error';
            my.result.type = 'Fatal';

            result = false;
        }
    }
    return result;
}
